// Verdant site — generated by Panda. The scripts in this folder are the only
// "source" Panda extracts from (see panda.config.ts `include`): every
// css()/pattern()/recipe() call is a literal call, so `panda cssgen` can
// statically find it and emit exactly the CSS the pages use, nothing more.
//
// This file is orchestration only. Page content lives in ./pages, the shared
// chrome in ./shell.mjs, shared style bindings in ./styles.mjs, and the
// browser-side scripts in ./client.
import { writeFileSync, mkdirSync } from 'node:fs'
import { COMPONENTS_ROUTE, GREEN_WEB_ROUTE } from './config.mjs'
import { copyDir, minifyHtml } from './lib/html.mjs'
import { page } from './shell.mjs'
import {
  heroHtml, statsHtml, stagesHtml, paletteHtml, tokensHtml, scoreHtml, pandaHtml, ctaHtml,
} from './pages/home.mjs'
import { componentsBody } from './pages/components.mjs'
import { greenWebBody, greenWebMeta } from './pages/green-web.mjs'
import { notFoundBody, offlineBody } from './pages/status.mjs'
import { themeToggleJs } from './client/theme-toggle.mjs'
import { motionPreviewJs } from './client/gallery.mjs'
import { swRegisterJs } from './client/sw-register.mjs'
import { swJs } from './client/sw.mjs'

mkdirSync('dist', { recursive: true })
writeFileSync('dist/theme-toggle.js', themeToggleJs)
// The gallery's motion preview needs the DOM, so it ships separately and deferred.
writeFileSync('dist/gallery.js', motionPreviewJs)
writeFileSync('dist/sw-register.js', swRegisterJs)
writeFileSync('dist/sw.js', swJs)
copyDir('public', 'dist')

writeFileSync('dist/index.html', minifyHtml(page({
  title: 'Verdant — Sustainable Defaults for the Green Web',
  description: 'Verdant is a lightweight design-system starter with defaults aligned to selected Web Sustainability Guidelines. Built with PandaCSS.',
  path: '/',
  active: 'home',
  jsonLd: {
    '@context': 'https://schema.org',
    '@type': 'WebSite',
    name: 'Verdant',
    description: 'A lightweight design-system starter with defaults aligned to selected Web Sustainability Guidelines.',
    url: 'https://verdant-wsg-demo.netlify.app/',
  },
  bodyHtml: heroHtml + statsHtml + stagesHtml + paletteHtml + tokensHtml + scoreHtml + pandaHtml + ctaHtml,
})))

writeFileSync('dist/components.html', minifyHtml(page({
  title: 'Components — Verdant',
  description: 'Documented component specimens for the Verdant design system: links, buttons, fields, switches, status cards, and loading patterns.',
  path: COMPONENTS_ROUTE,
  active: 'components',
  crumb: 'Components',
  bodyHtml: componentsBody,
  scripts: ['/gallery.js'],
})))

writeFileSync('dist/green-web.html', minifyHtml(page({
  title: greenWebMeta.pageTitle,
  description: greenWebMeta.description,
  path: GREEN_WEB_ROUTE,
  active: 'green-web',
  crumb: greenWebMeta.crumb,
  bodyHtml: greenWebBody,
})))

writeFileSync('dist/404.html', minifyHtml(page({
  title: 'Page not found — Verdant',
  description: 'The page you were looking for does not exist.',
  path: '/404.html',
  active: '',
  bodyHtml: notFoundBody,
})))

writeFileSync('dist/offline.html', minifyHtml(page({
  title: 'Offline — Verdant',
  description: 'You are offline and this page is not available yet.',
  path: '/offline.html',
  active: '',
  bodyHtml: offlineBody,
})))

console.log('Wrote dist/index.html, dist/components.html, dist/green-web.html, dist/404.html, dist/offline.html')
